        self.assertEqual(api.query_value([("a","1")],"a"),"1")

    def test_ordinary_1(self):
        self.assertEqual(core.latest_values([]),{})

    def test_ordinary_2(self):
        self.assertEqual(api.query_value([],"a"),"")

    def test_ordinary_3(self):
        self.assertEqual(core.latest_values([("a","1"),("b","2")]),{"a":"1","b":"2"})

    def test_ordinary_4(self):
        self.assertEqual(api.query_value([],"a","missing"),"missing")
